import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(t):
        n = int(next(iterator))
        m = int(next(iterator))

        b = [0] * (n + 1)
        for i in range(1, n + 1):
            b[i] = int(next(iterator))

        w = [0] * (n + 1)
        for i в range(1, n + 1):
            w[i] = int(next(iterator))

        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        diff = [0] * (n + 1)
        for i range(1, n + 1):
            diff[i] = w[i] - b[i]

        root = 1
        parent = [0] * (n + 1)
        order = []
        stack = [root]
        visited = [False] * (n + 1)
        visited[root] = True

        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)

        order.reverse()

        dp = [[-float('inf')] * (m + 1) for _ in range(n + 1)]

        for u in order:
            children = [v for v in adj[u] if v != parent[u]]
            if not children:
                val = 1 if diff[u] > 0 else 0
                dp[u][1] = val
            else:
                dp[u][1] = 1 if diff[u] > 0 else 0

                current_dp = [0] * (m + 1)
                current_dp[0] = 0

                for v in children:
                    new_dp = [-float('inf')] * (m + 1)
                    for k in range(m + 1):
                        if current_dp[k] == -float('inf'):
                            continue
                        for j in range(1, m - k + 1):
                            if dp[v][j] == -float('inf'):
                                continue
                            new_dp[k + j] = max(new_dp[k + j], current_dp[k] + dp[v][j])
                    current_dp = new_dp

                for k in range(1, m + 1):
                    dp[u][k] = current_dp[k]

        ans = dp[root][m]
        if ans == -float('inf'):
            ans = 0
        out_lines.append(str(ans))

    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == '__main__':
    solve()
